fn main() -> Void {
    let sizes: Int[] = [3, 2, 4, 1, 3, 2];
    let totalSlots: Int = 11;
    let occupied: Int[] = [0; totalSlots];

    loop t in 0..length(sizes) {
        let size: Int = sizes[t];
        let placed: Bool = false;
        loop s in 0..totalSlots - size + 1 {
            let fits: Bool = true;
            loop k in 0..size {
                if occupied[s + k] == 1 {
                    fits = false;
                    break;
                }
            }
            if fits {
                loop k in 0..size {
                    occupied[s + k] = 1;
                }
                if size == 1 {
                    fx {
                        println("Tray ", t + 1, ": slots ", s + 1);
                    }
                } else {
                    fx {
                        println("Tray ", t + 1, ": slots ", s + 1, "-", s + size);
                    }
                }
                placed = true;
                break;
            }
        }
        if !placed {
            fx {
                println("Tray ", t + 1, ": hand wash");
            }
        }
    }
    ret;
}

fn main() -> Void {
    let volumes: Int[] = [4, 2, 5, 3, 1, 6];
    let bins: Int[] = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    let n: Int = 9;

    loop li in 0..length(volumes) {
        let v: Int = volumes[li];
        let placed: Bool = false;
        loop s in 0..n - v + 1 {
            let fits: Bool = true;
            loop k in 0..v {
                if bins[s + k] != 0 {
                    fits = false;
                    break;
                }
            }
            if fits {
                loop k in 0..v {
                    bins[s + k] = 1;
                }
                if v == 1 {
                    fx {
                        println("Load ", li + 1, ": bins ", s + 1);
                    }
                } else {
                    fx {
                        println("Load ", li + 1, ": bins ", s + 1, "-", s + v);
                    }
                }
                placed = true;
                break;
            }
        }
        if !placed {
            fx {
                println("Load ", li + 1, ": elsewhere");
            }
        }
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [150, 0, 200, 175],
        [0, 125, 0, 100],
        [300, 150, 250, 0]
    ];

    let selRow: Int = 1;
    let selCol: Int = 2;

    let selPrice: Int = grid[selRow][selCol];

    let rowCount: Int = 0;
    loop c in 0..4 {
        if grid[selRow][c] != 0 {
            rowCount = rowCount + 1;
        }
    }

    let colCount: Int = 0;
    loop r in 0..3 {
        if grid[r][selCol] != 0 {
            colCount = colCount + 1;
        }
    }

    let maxPrice: Int = 0;
    let total: Int = 0;
    let nonEmpty: Int = 0;
    loop r in 0..3 {
        loop c in 0..4 {
            let p: Int = grid[r][c];
            if p != 0 {
                if p > maxPrice {
                    maxPrice = p;
                }
                total = total + p;
                nonEmpty = nonEmpty + 1;
            }
        }
    }

    let avg: Real = 0.0;
    if nonEmpty > 0 {
        avg = total * 1.0 / nonEmpty;
    }

    fx {
        if selPrice == 0 {
            println("Item: empty");
        } else {
            println("Item: ", selPrice);
        }
        println("Row count: ", rowCount);
        println("Column count: ", colCount);
        println("Max price: ", maxPrice);
        println("Avg price: ", format_float(avg, 2));
    }

    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [0, 1, 0, 0],
        [0, 2, 1, 0],
        [1, 0, 0, 0],
        [0, 0, 1, 2]
    ];

    let stopCol: Int = 3;
    loop c in 0..4 {
        if grid[0][c] != 0 {
            stopCol = c;
            break;
        }
    }

    let blockedRows: Int = 0;
    loop r in 0..4 {
        let hasBlocked: Bool = false;
        loop c in 0..4 {
            if grid[r][c] == 2 {
                hasBlocked = true;
            }
        }
        if hasBlocked {
            blockedRows = blockedRows + 1;
        }
    }

    let occupied: Int = 0;
    let clearCells: Int = 0;
    loop r in 0..4 {
        loop c in 0..4 {
            if grid[r][c] == 1 {
                occupied = occupied + 1;
            }
            if grid[r][c] == 0 {
                clearCells = clearCells + 1;
            }
        }
    }

    let row2Activity: Int = 0;
    loop c in 0..4 {
        row2Activity = row2Activity + grid[2][c];
    }

    fx {
        println("Train stop: 0,", stopCol);
        println("Blocked rows: ", blockedRows);
        println("Occupied: ", occupied);
        println("Clear cells: ", clearCells);
        println("Row 2 activity: ", row2Activity);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [1, 1, 0, 2, 1],
        [0, 2, 1, 1, 0],
        [1, 1, 1, 0, 2],
        [2, 0, 1, 1, 1],
        [1, 1, 0, 2, 1]
    ];

    let planted: Int = 0;
    let harvested: Int = 0;
    let untilled: Int = 0;
    let longestRun: Int = 0;
    let col3Planted: Int = 0;

    loop r in 0..5 {
        let currentRun: Int = 0;
        loop c in 0..5 {
            let v: Int = grid[r][c];
            if v == 1 {
                planted = planted + 1;
                currentRun = currentRun + 1;
                if currentRun > longestRun {
                    longestRun = currentRun;
                }
            } else {
                currentRun = 0;
            }
            if v == 2 {
                harvested = harvested + 1;
            }
            if v == 0 {
                untilled = untilled + 1;
            }
            if c == 3 && v == 1 {
                col3Planted = col3Planted + 1;
            }
        }
    }

    fx {
        println("Planted: ", planted);
        println("Harvested: ", harvested);
        println("Untilled: ", untilled);
        println("Center row: ", grid[2][0], " ", grid[2][1], " ", grid[2][2], " ", grid[2][3], " ", grid[2][4]);
        println("Longest planted run: ", longestRun);
        println("Col 3 planted: ", col3Planted);
    }
    ret;
}

fn main() -> Void {
    let board: Int[][] = [
        [1, 1, 1, 2, 2, 2],
        [1, 1, 2, 2, 2, 2],
        [1, 2, 2, 2, 1, 2],
        [1, 1, 2, 1, 1, 2],
        [1, 1, 1, 1, 2, 2],
        [1, 1, 1, 2, 2, 2]
    ];

    let p1: Int = 0;
    let p2: Int = 0;
    let row0p1: Int = 0;
    let col5p2: Int = 0;
    let diagp1: Int = 0;

    loop r in 0..6 {
        loop c in 0..6 {
            let v: Int = board[r][c];
            if v == 1 {
                p1 = p1 + 1;
            } else {
                p2 = p2 + 1;
            }
            if r == 0 && v == 1 {
                row0p1 = row0p1 + 1;
            }
            if c == 5 && v == 2 {
                col5p2 = col5p2 + 1;
            }
            if r == c && v == 1 {
                diagp1 = diagp1 + 1;
            }
        }
    }

    let leader: Int = 0;
    if p1 > p2 {
        leader = 1;
    } else if p2 > p1 {
        leader = 2;
    }

    let diff: Int = abs(p1 - p2);

    fx {
        println("Player 1 cells: ", p1);
        println("Player 2 cells: ", p2);
        println("Row 0 P1: ", row0p1);
        println("Col 5 P2: ", col5p2);
        println("Diagonal 1 P1: ", diagp1);
        println("Leader: ", leader);
        println("Score diff: ", diff);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [3, 0, 5, 2, 0, 1, 4, 0],
        [0, 2, 0, 0, 6, 0, 0, 3],
        [1, 0, 0, 4, 0, 0, 2, 0],
        [0, 0, 7, 0, 0, 5, 0, 0],
        [2, 1, 0, 0, 3, 0, 0, 4]
    ];

    let total: Int = 0;
    let empty: Int = 0;
    let row1: Int = 0;
    let col4: Int = 0;
    let maxVal: Int = -1;
    let maxR: Int = 0;
    let maxC: Int = 0;

    loop r in 0..5 {
        loop c in 0..8 {
            let v: Int = grid[r][c];
            total = total + v;
            if v == 0 {
                empty = empty + 1;
            }
            if r == 1 {
                row1 = row1 + v;
            }
            if c == 4 {
                col4 = col4 + v;
            }
            if v > maxVal {
                maxVal = v;
                maxR = r;
                maxC = c;
            }
        }
    }

    let avg: Real = total * 1.0 / 40.0;
    let avgR: Real = round_to(avg, 2);

    fx {
        println("Total fish: ", total);
        println("Empty zones: ", empty);
        println("Row 1 fish: ", row1);
        println("Col 4 fish: ", col4);
        println("Max zone: ", maxR, ",", maxC);
        println("Avg fish: ", format_float(avgR, 2));
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [45, 0, 30, 60, 0, 20],
        [0, 50, 0, 0, 40, 0],
        [25, 0, 55, 0, 35, 0],
        [0, 0, 45, 60, 0, 15]
    ];

    let rows: Int = length(grid);
    let cols: Int = length(grid[0]);

    let items: Int = 0;
    let quickDry: Int = 0;
    let readyBy45: Int = 0;
    let total: Int = 0;
    let longestTotal: Int = 0;
    let col3Max: Int = 0;

    loop r in 0..rows {
        let rowTotal: Int = 0;
        loop c in 0..cols {
            let v: Int = grid[r][c];
            if v > 0 {
                items = items + 1;
                total = total + v;
                rowTotal = rowTotal + v;
                if v <= 30 {
                    quickDry = quickDry + 1;
                }
                if v <= 45 {
                    readyBy45 = readyBy45 + 1;
                }
                if c == 2 && v > col3Max {
                    col3Max = v;
                }
            }
        }
        if rowTotal > longestTotal {
            longestTotal = rowTotal;
        }
    }

    let avg: Real = total * 1.0 / items;

    fx {
        println("Items: ", items);
        println("Quick-dry: ", quickDry);
        println("Longest total: ", longestTotal);
        println("Col 3 max: ", col3Max);
        println("Avg time: ", format_float(avg, 1));
        println("Ready by 45: ", readyBy45);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [2, 5, 1, 0, 3],
        [4, 0, 2, 6, 1],
        [0, 3, 5, 0, 2],
        [1, 2, 0, 4, 3]
    ];

    let total: Int = 0;
    let fullCount: Int = 0;
    let emptyCount: Int = 0;
    let row1Total: Int = 0;
    let col2Total: Int = 0;
    let topRowFull: Bool = true;

    loop r in 0..4 {
        loop c in 0..5 {
            let v: Int = grid[r][c];
            total = total + v;
            if v >= 3 {
                fullCount = fullCount + 1;
            }
            if v == 0 {
                emptyCount = emptyCount + 1;
            }
            if r == 1 {
                row1Total = row1Total + v;
            }
            if c == 2 {
                col2Total = col2Total + v;
            }
            if r == 0 && v < 3 {
                topRowFull = false;
            }
        }
    }

    let avg: Real = total * 1.0 / 20.0;
    let avgRounded: Real = round_to(avg, 2);

    let topLabel: Text = if topRowFull { "yes" } else { "no" };

    fx {
        println("Total trays: ", total);
        println("Full shelves: ", fullCount);
        println("Empty shelves: ", emptyCount);
        println("Row 1 total: ", row1Total);
        println("Col 2 total: ", col2Total);
        println("Avg trays: ", format_float(avgRounded, 2));
        println("Top row full: ", topLabel);
    }
    ret;
}

@pure
fn digitSum(n: Int) -> Int {
    let s: Int = 0;
    let x: Int = n;
    loop {
        if x == 0 {
            break;
        }
        s = s + x % 10;
        x = x div 10;
    }
    ret s;
}

@pure
fn isGolden(code: Int) -> Bool {
    if code % 3 != 0 {
        ret false;
    }
    let ds: Int = digitSum(code);
    if ds <= 10 {
        ret false;
    }
    if code % ds != 0 {
        ret false;
    }
    ret true;
}

fn main() -> Void {
