fn main() -> Void {
    let codes: Int[] = [17, 77, 123, 456, 777, 1000];
    let total: Int = 0;

    loop code in codes {
        let value: Int = 0;
        let temp: Int = code;
        let place: Int = 1;
        loop temp > 0 {
            let digit: Int = temp % 10;
            value = value + digit * place;
            place = place * 8;
            temp = temp div 10;
        }
        total = total + value;
        fx {
            println("OCTAL CODE: ", code);
        }
    }

    fx {
        println("SUM BASE10: ", total);
    }
    ret;
}

fn main() -> Void {
    let hulls: Int[] = [140, 231, 342, 455, 567, 678, 784, 896];
    let dueCount: Int = 0;

    loop h in hulls {
        let lastTwo: Int = h % 100;
        let tens: Int = lastTwo div 10;
        let ones: Int = lastTwo % 10;
        let digitSum: Int = tens + ones;
        if h % 7 == 0 && digitSum > 5 {
            dueCount = dueCount + 1;
            fx {
                println(h, ": DUE");
            }
        } else {
            fx {
                println(h, ": OK");
            }
        }
    }

    fx {
        println("DUE COUNT: ", dueCount);
    }

    ret;
}

@pure
fn checksum(n: Int) -> Int {
    let total: Int = 0;
    let pos: Int = 1;
    let x: Int = n;
    loop x > 0 {
        let d: Int = x % 10;
        total = total + d * pos;
        x = x div 10;
        pos = pos + 1;
    }
    ret total;
}

fn main() -> Void {
    let calls: Int[] = [123, 456, 789, 101, 202, 303, 404, 505];
    let sum: Int = 0;
    loop c in calls {
        let cs: Int = checksum(c);
        sum = sum + cs;
        fx {
            println(c, ": ", cs);
        }
    }
    let avg: Real = sum * 1.0 / length(calls);
    fx {
        println("AVG CKSUM: ", format_float(avg, 2));
    }
    ret;
}

@pure
fn isPalindrome(n: Int) -> Bool {
    let s: Text = int_to_text(n);
    let len: Int = string_len(s);
    loop i in 0..(len div 2) {
        if s[i] != s[len - 1 - i] {
            ret false;
        }
    }
    ret true;
}

