@pure
fn to_base4(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let digits: Int[] = [];
    let v: Int = n;
    loop {
        let d: Int = v % 4;
        digits = digits + [d];
        v = v div 4;
        if v == 0 {
            break;
        }
    }
    let len: Int = length(digits);
    let result: Text = "";
    loop i in 0..len {
        result = result + int_to_text(digits[len - 1 - i]);
    }
    ret result;
}

fn main() -> Void {
    let temps: Int[] = [5, 10, 15, 20, 25, 30, 35, 40];
    let longest: Int = 0;
    loop t in temps {
        let b4: Text = to_base4(t);
        let blen: Int = string_len(b4);
        if blen > longest {
            longest = blen;
        }
        fx {
            println(t, ": ", b4);
        }
    }
    fx {
        println("LONGEST B4: ", longest);
    }
    ret;
}

