@pure
fn isVerified(id: Int) -> Bool {
    let ds: Int = digitSum(id);
    if ds == 0 {
        ret false;
    }
    if id % ds != 0 {
        ret false;
    }
    let q: Int = id div ds;
    if q > 1 {
        ret true;
    }
    ret false;
}

