@pure
fn is_valid_code(code: Text) -> Bool {
    if string_len(code) != 4 {
        ret false;
    }
    let c0: Text = code[0];
    let c1: Text = code[1];
    let c2: Text = code[2];
    let c3: Text = code[3];
    let o0: Int = ord(c0);
    let o1: Int = ord(c1);
    let o2: Int = ord(c2);
    let o3: Int = ord(c3);
    if o0 < 65 || o0 > 90 {
        ret false;
    }
    if o1 < 65 || o1 > 90 {
        ret false;
    }
    if o2 < 48 || o2 > 57 {
        ret false;
    }
    if o3 < 48 || o3 > 57 {
        ret false;
    }
    ret true;
}

fn main() -> Void {
    let codes: Text[] = ["AB12", "XY99", "ZZ00", "A1B2", "CD34", "EF56", "GH78", "IJ90", "KL12", "M3N4", "OP56", "QR78"];
    let validCount: Int = 0;
    let invalidCount: Int = 0;
    loop code in codes {
        if is_valid_code(code) {
            validCount = validCount + 1;
            fx { println(code, ": VALID"); }
        } else {
            invalidCount = invalidCount + 1;
            fx { println(code, ": INVALID"); }
        }
    }
    fx {
        println("");
        println("VALID: ", validCount, " INVALID: ", invalidCount);
    }
    ret;
}

fn titleCase(s: Text) -> Text {
    let words: Text[] = split(s, " ");
    let out: Text[] = [];
    loop w in words {
        let n: Int = string_len(w);
        if n == 0 {
            out = out + [""];
        } else {
            let first: Text = upper(w[0..1]);
            let rest: Text = lower(w[1..]);
            out = out + [first + rest];
        }
    }
    ret join(out, " ");
}

