@pure
fn isUpper(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 65 && c <= 90;
}

@pure
fn isDigit(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 48 && c <= 57;
}

@pure
fn isWellFormed(label: Text) -> Bool {
    if string_len(label) != 7 {
        ret false;
    }
    if !isUpper(label[0]) {
        ret false;
    }
    if !isUpper(label[1]) {
        ret false;
    }
    if !isUpper(label[2]) {
        ret false;
    }
    if label[3] != "-" {
        ret false;
    }
    if !isDigit(label[4]) {
        ret false;
    }
    if !isDigit(label[5]) {
        ret false;
    }
    ret true;
}

fn main() -> Void {
    let labels: Text[] = ["ABC-12", "DEF-34", "GHI-5", "JK-67", "LMN-89", "OPQ-0", "RS-TU", "VWX-10"];
    let okCount: Int = 0;
    let badCount: Int = 0;

    loop i in 0..length(labels) {
        let label: Text = labels[i];
        if isWellFormed(label) {
            okCount = okCount + 1;
            fx {
                println(label, ": OK");
            }
        } else {
            badCount = badCount + 1;
            fx {
                println(label, ": BAD");
            }
        }
    }

    fx {
