fn isUpper(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 65 && c <= 90;
}

fn isDigit(ch: Text) -> Bool {
    let c: Int = ord(ch);
    ret c >= 48 && c <= 57;
}

fn validate(code: Text) -> Bool {
    if string_len(code) != 9 {
        ret false;
    }
    if !isUpper(code[0]) {
        ret false;
    }
    if !isUpper(code[1]) {
        ret false;
    }
    if ord(code[0]) > ord(code[1]) {
        ret false;
    }
    if code[2] != "-" {
        ret false;
    }
    loop i in 3..9 {
        if !isDigit(code[i]) {
            ret false;
        }
    }
    ret true;
}

