fn main() -> Void {
    let data: Text = "NAME=Spade\nTYPE=Digging\nQTY=2\nSHARP=No\nNAME=Pruner\nTYPE=Cutting\nQTY=4\nSHARP=Yes\nNAME=Rake\nTYPE=Cleanup\nQTY=1\nSHARP=No\nNAME=Shears\nTYPE=Cutting\nQTY=3\nSHARP=Yes\nNAME=Fork\nTYPE=Digging\nQTY=2\nSHARP=No";
    let lines: Text[] = split(data, "\n");
    let types: Text[] = [];
    let totalQty: Int[] = [];
    let sharpQty: Int[] = [];
    let curName: Text = "";
    let curType: Text = "";
    let curQty: Int = 0;
    let curSharp: Bool = false;
    let inBlock: Bool = false;

    loop line in lines {
        if line == "" {
            continue;
        }
        let eqIdx: Int = index_of(line, "=");
        if eqIdx < 0 {
            continue;
        }
        let key: Text = line[0..eqIdx];
        let val: Text = line[eqIdx + 1..];
        if key == "NAME" {
            if inBlock {
                let found: Int = -1;
                loop i in 0..length(types) {
                    if types[i] == curType {
                        found = i;
                        break;
                    }
                }
                if found >= 0 {
                    totalQty[found] = totalQty[found] + curQty;
                    if curSharp {
                        sharpQty[found] = sharpQty[found] + curQty;
                    }
                } else {
                    types = types + [curType];
                    totalQty = totalQty + [curQty];
                    if curSharp {
                        sharpQty = sharpQty + [curQty];
                    } else {
                        sharpQty = sharpQty + [0];
                    }
                }
            }
            curName = val;
            inBlock = true;
        } else if key == "TYPE" {
            curType = val;
        } else if key == "QTY" {
            curQty = parse_int(val);
        } else if key == "SHARP" {
            curSharp = (val == "Yes");
        }
    }

    if inBlock {
        let found: Int = -1;
        loop i in 0..length(types) {
            if types[i] == curType {
                found = i;
                break;
            }
        }
        if found >= 0 {
            totalQty[found] = totalQty[found] + curQty;
            if curSharp {
                sharpQty[found] = sharpQty[found] + curQty;
            }
        } else {
            types = types + [curType];
            totalQty = totalQty + [curQty];
            if curSharp {
                sharpQty = sharpQty + [curQty];
            } else {
                sharpQty = sharpQty + [0];
            }
        }
    }

    let grandTotal: Int = 0;
    let bestIdx: Int = 0;
    let bestSharp: Int = -1;

    loop i in 0..length(types) {
        grandTotal = grandTotal + totalQty[i];
        if sharpQty[i] > bestSharp {
            bestSharp = sharpQty[i];
            bestIdx = i;
        }
    }

    fx {
        loop i in 0..length(types) {
            let toolWord: Text = if totalQty[i] == 1 { "tool" } else { "tools" };
            println(types[i], ": ", totalQty[i], " ", toolWord, ", ", sharpQty[i], " sharp");
        }
        println("Sharpest type: ", types[bestIdx]);
        println("Total tools: ", grandTotal);
    }
    ret;
}

fn main() -> Void {
    let start: Int[] = [0, 2, 5, 6];
    let dur: Int[] = [3, 4, 2, 3];
    let n: Int = 4;
    let armFree: Int = 0;
    let schedule: Int[] = [];

    loop i in 0..n {
        let s: Int = start[i];
        let d: Int = dur[i];
        let actualStart: Int = if s > armFree { s } else { armFree };
        let actualEnd: Int = actualStart + d;
        loop m in actualStart..actualEnd {
            schedule = schedule + [i + 1];
        }
        armFree = actualEnd;
    }

    loop m in 0..10 {
        let running: Int = 0;
        loop i in 0..n {
            if m < length(schedule) && schedule[m] == i + 1 {
                running = i + 1;
            }
        }
        if running == 0 {
            fx { println("Minute ", m, ": idle"); }
        } else {
            fx { println("Minute ", m, ": ", running); }
        }
    }
    ret;
}

fn main() -> Void {
