    let classBlocks: Int[] = [1, 1, 3, 3, 5];
    let n: Int = length(classRooms);

    let conflicts: Int = 0;
    loop i in 0..n {
        loop j in i + 1..n {
            if classRooms[i] == classRooms[j] && classBlocks[i] == classBlocks[j] {
                conflicts = conflicts + 1;
            }
        }
    }

    let totalHours: Int = n;
    let usedPairs: Int = 0;
    loop r in 0..length(rooms) {
        loop i in 0..n {
            if classRooms[i] == rooms[r] {
                usedPairs = usedPairs + 1;
            }
        }
    }
    let freePairs: Int = 18 - usedPairs;

    fx {
        println("Conflicts: ", conflicts);
        loop r in 0..length(rooms) {
            let blocks: Int[] = [];
            loop b in 1..7 {
                let found: Bool = false;
                loop i in 0..n {
                    if classRooms[i] == rooms[r] && classBlocks[i] == b {
                        found = true;
                        break;
                    }
                }
                if found {
                    blocks = blocks + [b];
                }
            }
            let parts: Text[] = [];
            loop b in blocks {
                parts = parts + [int_to_text(b)];
            }
            println("Room ", int_to_text(rooms[r]), " blocks: ", join(parts, " "));
        }
        println("Total class-hours: ", totalHours);
        println("Free room-blocks: ", freePairs);
    }
    ret;
