    let durs: Int[] = [30, 45, 20, 60, 25, 35, 20];
    let n: Int = 7;

    let b1: Int = 0;
    let b2: Int = 0;
    let b3: Int = 0;
    let b4: Int = 0;

    loop i in 0..n {
        loop j in i + 1..n {
            if boards[i] == boards[j] {
                let si: Int = starts[i];
                let ei: Int = starts[i] + durs[i];
                let sj: Int = starts[j];
                let ej: Int = starts[j] + durs[j];
                if si < ej && sj < ei {
                    if boards[i] == 1 {
                        b1 = b1 + 1;
                    }
                    if boards[i] == 2 {
                        b2 = b2 + 1;
                    }
                    if boards[i] == 3 {
                        b3 = b3 + 1;
                    }
                    if boards[i] == 4 {
                        b4 = b4 + 1;
                    }
                }
            }
        }
    }

    let busy: Int = 0;
    loop minute in 0..100 {
        let active: Bool = false;
