fn main() -> Void {
    let arrivals: Int[] = [0, 1, 3, 7, 12, 12];
    let clerkFree: Int[] = [0, 0];
    let serviceTime: Int = 6;

    loop i in 0..length(arrivals) {
        let guestNum: Int = i + 1;
        let arrive: Int = arrivals[i];
        let c1: Int = clerkFree[0];
        let c2: Int = clerkFree[1];
        let clerk: Int = 0;
        let start: Int = 0;

        if c1 <= c2 {
            clerk = 1;
            if arrive >= c1 {
                start = arrive;
            } else {
                start = c1;
            }
        } else {
            clerk = 2;
            if arrive >= c2 {
                start = arrive;
            } else {
                start = c2;
            }
        }

        let waited: Int = start - arrive;
        let finish: Int = start + serviceTime;

        if clerk == 1 {
            clerkFree[0] = finish;
        } else {
            clerkFree[1] = finish;
        }

        fx {
            println("Guest ", guestNum, ": clerk ", clerk, ", waited ", waited, " minutes");
        }
    }

    ret;
}

