fn main() -> Void {
    let pots: Text[] = ["A", "B", "C", "D"];
    let total: Int = 0;
    let startA: Int = 0;
    let bNextC: Int = 0;
    let dEnd: Int = 0;
    let first5: Text[] = [];

    loop a in pots {
        loop b in pots {
            if b == a {
                continue;
            }
            loop c in pots {
                if c == a or c == b {
                    continue;
                }
                loop d in pots {
                    if d == a or d == b or d == c {
                        continue;
                    }
                    let arr: Text = a + b + c + d;
                    total = total + 1;
                    if a == "A" {
                        startA = startA + 1;
                    }
                    if (a == "B" and b == "C") or (a == "C" and b == "B") or (b == "B" and c == "C") or (b == "C" and c == "B") or (c == "B" and d == "C") or (c == "C" and d == "B") {
                        bNextC = bNextC + 1;
                    }
                    if a == "D" or d == "D" {
                        dEnd = dEnd + 1;
                    }
                    if length(first5) < 5 {
                        first5 = first5 + [arr];
                    }
                }
            }
        }
    }

    let sorted5: Text[] = sorted(first5);

    fx {
        println("Total arrangements: ", total);
        println("Arrangements starting with A: ", startA);
        println("Arrangements with B next to C: ", bNextC);
        println("Arrangements with D at an end: ", dEnd);
        let line: Text = "First 5 arrangements in alphabetical order: ";
        loop i in 0..length(sorted5) {
            if i > 0 {
                line = line + " ";
            }
            line = line + sorted5[i];
        }
        println(line);
    }
    ret;
}

