    let allEqual: Int = 0;
    let exactlyOneSix: Int = 0;
    let nonDecreasing: Int = 0;
    let sum14: Int = 0;
    let noConsecutive: Int = 0;
    let found: Bool = false;
    let bestA: Int = 0;
    let bestB: Int = 0;
    let bestC: Int = 0;
    let bestD: Int = 0;

    loop a in 1..7 {
        loop b in 1..7 {
            loop c in 1..7 {
                loop d in 1..7 {
                    total = total + 1;

                    if a == b && b == c && c == d {
                        allEqual = allEqual + 1;
                    }

                    let sixCount: Int = 0;
                    if a == 6 { sixCount = sixCount + 1; }
                    if b == 6 { sixCount = sixCount + 1; }
                    if c == 6 { sixCount = sixCount + 1; }
                    if d == 6 { sixCount = sixCount + 1; }
                    if sixCount == 1 {
                        exactlyOneSix = exactlyOneSix + 1;
                    }

                    if a <= b && b <= c && c <= d {
                        nonDecreasing = nonDecreasing + 1;
                    }

                    let s: Int = a + b + c + d;
                    if s == 14 {
                        sum14 = sum14 + 1;
                        if !found {
                            found = true;
                            bestA = a;
                            bestB = b;
                            bestC = c;
                            bestD = d;
