    let threeEach: Int = 0;
    let aAtT1: Int = 0;
    let abSame: Int = 0;
    let t1More: Int = 0;
    let t1AB: Int = 0;

    loop mask in 1..(1 << n) {
        let t1Count: Int = 0;
        let t2Count: Int = 0;
        let aInT1: Bool = false;
        let bInT1: Bool = false;
        let aInT2: Bool = false;
        let bInT2: Bool = false;

        loop i in 0..n {
            if (mask & (1 << i)) != 0 {
                t1Count = t1Count + 1;
                if i == 0 {
                    aInT1 = true;
                }
                if i == 1 {
                    bInT1 = true;
                }
            } else {
                t2Count = t2Count + 1;
                if i == 0 {
                    aInT2 = true;
                }
                if i == 1 {
                    bInT2 = true;
                }
            }
        }

        if t1Count == 0 || t2Count == 0 {
