    }
    ret;
}

@pure
fn countPathsBetween(r1: Int, c1: Int, r2: Int, c2: Int, avoidDiag: Bool) -> Int {
    if r1 > r2 || c1 > c2 {
        ret 0;
    }
    if r1 == r2 && c1 == c2 {
        if avoidDiag && r1 == c1 && !(r1 == 1 && c1 == 1) && !(r1 == 4 && c1 == 4) {
            ret 0;
        }
        ret 1;
    }
    if avoidDiag && r1 == c1 && !(r1 == 1 && c1 == 1) && !(r1 == 4 && c1 == 4) {
        ret 0;
    }
    ret countPathsBetween(r1 + 1, c1, r2, c2, avoidDiag) + countPathsBetween(r1, c1 + 1, r2, c2, avoidDiag);
}

@pure
fn countThreeRights(r: Int, c: Int, targetR: Int, targetC: Int, avoidDiag: Bool, rights: Int, downMade: Bool) -> Int {
    if r == targetR && c == targetC {
        if downMade && rights == 3 {
            ret 1;
        }
        ret 0;
    }
    if r > targetR || c > targetC {
        ret 0;
    }
    if avoidDiag && r == c && !(r == 1 && c == 1) && !(r == 4 && c == 4) {
        ret 0;
    }
    let total: Int = 0;
    if !downMade {
        total = total + countThreeRights(r + 1, c, targetR, targetC, avoidDiag, rights, true);
        if rights < 3 {
            total = total + countThreeRights(r, c + 1, targetR, targetC, avoidDiag, rights + 1, false);
        }
    } else {
        total = total + countThreeRights(r + 1, c, targetR, targetC, avoidDiag, rights, true);
        total = total + countThreeRights(r, c + 1, targetR, targetC, avoidDiag, rights, true);
    }
    ret total;
}

fn main() -> Void {
    let restricted: Int = countPathsBetween(1, 1, 4, 4, true);
    let unrestricted: Int = countPathsBetween(1, 1, 4, 4, false);

    let to23: Int = countPathsBetween(1, 1, 2, 3, false);
    let from23: Int = countPathsBetween(2, 3, 4, 4, false);
    let through23: Int = to23 * from23;

    let to34: Int = countPathsBetween(1, 1, 3, 4, false);
    let from34: Int = countPathsBetween(3, 4, 4, 4, false);
    let through34: Int = to34 * from34;

    let to23b: Int = countPathsBetween(1, 1, 2, 3, false);
    let mid23to34: Int = countPathsBetween(2, 3, 3, 4, false);
    let from34b: Int = countPathsBetween(3, 4, 4, 4, false);
    let both: Int = to23b * mid23to34 * from34b;

    let visit23Not34: Int = through23 - both;
    let threeRights: Int = countThreeRights(1, 1, 4, 4, true, 0, false);

    fx {
        println("Total paths (no diagonal cells except start/end): ", restricted);
        println("Total paths unrestricted: ", unrestricted);
        println("Paths that pass through (2,3): ", through23);
        println("Paths that pass through (3,4): ", through34);
        println("Paths that visit (2,3) but not (3,4): ", visit23Not34);
        println("Number of restricted paths that make exactly 3 right moves before the first down move: ", threeRights);
    }
    ret;
}

fn main() -> Void {
    let letters: Text[] = ["R", "O", "Y", "V"];
    let n: Int = 4;
    let orders: Text[] = [];

    loop a in 0..n {
        loop b in 0..n {
            if b == a {
                continue;
            }
            loop c in 0..n {
                if c == a or c == b {
                    continue;
                }
                loop d in 0..n {
                    if d == a or d == b or d == c {
                        continue;
                    }
                    let order: Text = letters[a] + letters[b] + letters[c] + letters[d];
                    orders = orders + [order];
                }
            }
        }
    }

    let total: Int = length(orders);
    let startR: Int = 0;
    let rBeforeV: Int = 0;
    let oyConsec: Int = 0;
    let alternating: Int = 0;

    loop i in 0..total {
        let o: Text = orders[i];
        if o[0] == "R" {
            startR = startR + 1;
        }
        let rPos: Int = -1;
        let vPos: Int = -1;
        loop j in 0..4 {
            if o[j] == "R" {
                rPos = j;
            }
            if o[j] == "V" {
                vPos = j;
            }
        }
        if rPos < vPos {
            rBeforeV = rBeforeV + 1;
        }
        if (o[0] == "O" and o[1] == "Y") or (o[0] == "Y" and o[1] == "O") or (o[1] == "O" and o[2] == "Y") or (o[1] == "Y" and o[2] == "O") or (o[2] == "O" and o[3] == "Y") or (o[2] == "Y" and o[3] == "O") {
            oyConsec = oyConsec + 1;
        }
        let p0w: Bool = o[0] == "R" or o[0] == "O";
        let p1w: Bool = o[1] == "R" or o[1] == "O";
        let p2w: Bool = o[2] == "R" or o[2] == "O";
        let p3w: Bool = o[3] == "R" or o[3] == "O";
        if (p0w and !p1w and p2w and !p3w) or (!p0w and p1w and !p2w and p3w) {
            alternating = alternating + 1;
        }
    }

    let sorted: Text[] = sorted(orders);
    let first6: Text = sorted[0] + " " + sorted[1] + " " + sorted[2] + " " + sorted[3] + " " + sorted[4] + " " + sorted[5];

    fx {
        println("Total visit orders: ", total);
        println("Orders starting with R: ", startR);
        println("Orders where R is visited before V: ", rBeforeV);
        println("Orders where O and Y are visited consecutively (in either order): ", oyConsec);
        println("Orders where the visits alternate between warm colors (R, O) and cool colors (Y, V): ", alternating);
        println("First 6 orders alphabetically: ", first6);
    }
    ret;
}

fn main() -> Void {
    let total: Int = 0;
    let exactly2w: Int = 0;
    let noAdjG: Int = 0;
    let sameEnds: Int = 0;
    let oneChange: Int = 0;
    let patterns: Text[] = [];

    loop mask in 0..32 {
        let p: Text = "";
        let wCount: Int = 0;
        let adjG: Bool = false;
        let changes: Int = 0;
        let prev: Text = "";

        loop i in 0..5 {
            let bit: Int = (mask >> i) & 1;
            let ch: Text = if bit == 0 { "G" } else { "W" };
            p = p + ch;
            if ch == "W" {
                wCount = wCount + 1;
            }
            if i > 0 {
                if ch == "G" && prev == "G" {
                    adjG = true;
                }
                if ch != prev {
                    changes = changes + 1;
                }
            }
            prev = ch;
        }

        total = total + 1;
        if wCount == 2 {
            exactly2w = exactly2w + 1;
        }
        if !adjG {
            noAdjG = noAdjG + 1;
        }
        if p[0] == p[4] {
            sameEnds = sameEnds + 1;
        }
        if changes == 1 {
            oneChange = oneChange + 1;
        }
        patterns = patterns + [p];
    }

    let sorted: Text[] = sorted(patterns);
    let first8: Text = "";
    loop i in 0..8 {
        if i > 0 {
            first8 = first8 + " ";
        }
        first8 = first8 + sorted[i];
    }

    fx {
        println("Total patterns: ", total);
        println("Patterns with exactly 2 white posts: ", exactly2w);
        println("Patterns with no two green posts adjacent: ", noAdjG);
        println("Patterns starting and ending with the same color: ", sameEnds);
        println("Patterns with exactly one color change (from post 1 to post 2, or ... only one transition in the whole row): ", oneChange);
        println("First 8 patterns alphabetically: ", first8);
    }
    ret;
}

fn countRuns(s: Text, ch: Text) -> Int {
    let runs: Int = 0;
    let prev: Text = "";
    loop i in 0..string_len(s) {
        let c: Text = s[i];
        if c == ch {
            if prev != ch {
                runs = runs + 1;
            }
        }
        prev = c;
    }
    ret runs;
}

fn main() -> Void {
    let records: Text[] = [];
    loop a in 0..2 {
        loop b in 0..2 {
            loop c in 0..2 {
                loop d in 0..2 {
                    loop e in 0..2 {
                        loop f in 0..2 {
                            let s: Text = (if a == 0 { "N" } else { "S" }) + (if b == 0 { "N" } else { "S" }) + (if c == 0 { "N" } else { "S" }) + (if d == 0 { "N" } else { "S" }) + (if e == 0 { "N" } else { "S" }) + (if f == 0 { "N" } else { "S" });
                            records = records + [s];
                        }
                    }
                }
            }
        }
    }

    let total: Int = length(records);
    let exactly3: Int = 0;
    let noAdj: Int = 0;
    let twoNruns: Int = 0;
    let firstLastDiff: Int = 0;
    let twoNtwoS: Int = 0;

    loop r in records {
        let nCount: Int = count(r, "N");
        let sCount: Int = 6 - nCount;
        if nCount == 3 && sCount == 3 {
            exactly3 = exactly3 + 1;
        }
        let hasAdj: Bool = false;
        loop i in 0..5 {
            if r[i] == "N" && r[i + 1] == "N" {
                hasAdj = true;
            }
        }
        if !hasAdj {
            noAdj = noAdj + 1;
        }
        let nRuns: Int = countRuns(r, "N");
        if nRuns == 2 {
            twoNruns = twoNruns + 1;
        }
        if r[0] != r[5] {
            firstLastDiff = firstLastDiff + 1;
        }
        let sRuns: Int = countRuns(r, "S");
        if nRuns == 2 && sRuns == 2 {
            twoNtwoS = twoNtwoS + 1;
        }
    }

    let sorted: Text[] = sorted(records);
    let first5: Text = sorted[0] + " " + sorted[1] + " " + sorted[2] + " " + sorted[3] + " " + sorted[4];

    fx {
        println("Total records: ", total);
        println("Records with exactly 3 N and 3 S: ", exactly3);
        println("Records with no two N adjacent: ", noAdj);
        println("Records with exactly 2 runs of N (a run is a maximal consecutive block of N): ", twoNruns);
        println("Records where the first and last hours differ: ", firstLastDiff);
        println("Number of records with exactly 2 runs of N and exactly 2 runs of S: ", twoNtwoS);
        println("First 5 records alphabetically: ", first5);
    }
    ret;
}

