                if m1 == m2 && m2 == m3 {
                    allEqual = allEqual + 1;
                }

                if p1 % 2 != 0 && p2 % 2 != 0 && p3 % 2 != 0 {
                    neverEven = neverEven + 1;
                }

                if p1 == 3 || p2 == 3 || p3 == 3 {
                    hits3 = hits3 + 1;
                }

                if !contains(positions, p3) {
                    positions = positions + [p3];
                }
            }
        }
