        let s: Int = spice[i];
        if s == 0 or s == 1 {
            mild = mild + 1;
            curMildRun = curMildRun + 1;
            if curMildRun > maxMildRun {
                maxMildRun = curMildRun;
            }
            curMediumRun = 0;
