        [0, 0, 2, 2, 2, 2, 2, 1, 1, 0, 0, 1, 2, 2, 2, 1, 0, 0],
        [1, 2, 2, 2, 1, 0, 0, 0, 2, 2, 2, 2, 2, 0, 1, 1, 1, 0],
        [2, 2, 1, 0, 0, 1, 1, 2, 2, 2, 1, 0, 0, 0, 2, 2, 2, 2],
        [0, 1, 1, 1, 2, 2, 2, 2, 0, 0, 1, 1, 0, 2, 2, 1, 1, 1]
    ];

    let days: Int = length(pitches);
    let cols: Int = length(pitches[0]);

    let totalTents: Int = 0;
    let doubles: Int = 0;
    let dayTotals: Int[] = [];
    let pitchDoubles: Int[] = [];

    loop c in 0..cols {
        pitchDoubles = pitchDoubles + [0];
    }

    loop d in 0..days {
        let dayTotal: Int = 0;
        loop c in 0..cols {
            let v: Int = pitches[d][c];
            dayTotal = dayTotal + v;
            totalTents = totalTents + v;
            if v >= 2 {
                doubles = doubles + 1;
                pitchDoubles[c] = pitchDoubles[c] + 1;
            }
        }
        dayTotals = dayTotals + [dayTotal];
    }

    let busiestDay: Int = 0;
    let busiestTotal: Int = dayTotals[0];
    loop d in 1..days {
        if dayTotals[d] > busiestTotal {
            busiestTotal = dayTotals[d];
            busiestDay = d;
        }
    }

    let busiestPitch: Int = 0;
    let pitchCount: Int = pitchDoubles[0];
    loop c in 1..cols {
        if pitchDoubles[c] > pitchCount {
            pitchCount = pitchDoubles[c];
            busiestPitch = c;
        }
    }

    let pitchMaxRun: Int = 0;
    let curRun: Int = 0;
    loop d in 0..days {
        if pitches[d][busiestPitch] >= 2 {
            curRun = curRun + 1;
            if curRun > pitchMaxRun {
                pitchMaxRun = curRun;
            }
        } else {
            curRun = 0;
        }
    }

    let maxBusyRun: Int = 0;
    let busyRun: Int = 0;
    loop d in 0..days {
        if dayTotals[d] >= 20 {
            busyRun = busyRun + 1;
            if busyRun > maxBusyRun {
                maxBusyRun = busyRun;
            }
        } else {
            busyRun = 0;
        }
    }

    fx {
        println("Days ", days);
        println("TotalTents ", totalTents);
        println("Doubles ", doubles);
        println("BusiestDay ", busiestDay);
        println("BusiestTotal ", busiestTotal);
        println("BusiestPitch ", busiestPitch);
        println("PitchCount ", pitchCount);
        println("PitchMaxRun ", pitchMaxRun);
        println("MaxBusyRun ", maxBusyRun);
    }
    ret;
}

