fn main() -> Void {
    let prefixes: Int[] = [902, 104, 305, 902, 710, 104, 505, 305, 710, 902, 104, 505];
    let n: Int = length(prefixes);

    let sorted: Int[] = [];
    let used: Bool[] = [];
    loop i in 0..n {
        used = used + [false];
    }

    loop rank in 0..n {
        let bestIdx: Int = -1;
        let bestVal: Int = 0;
        loop i in 0..n {
            if !used[i] {
                if bestIdx == -1 {
                    bestIdx = i;
                    bestVal = prefixes[i];
                } else if prefixes[i] < bestVal {
                    bestIdx = i;
                    bestVal = prefixes[i];
                }
            }
        }
        used[bestIdx] = true;
        sorted = sorted + [bestVal];
    }

    fx {
        loop i in 0..n {
            println("E ", i + 1, ": ", sorted[i]);
        }
        println("");

        let distinct: Int[] = [];
        loop i in 0..n {
            let found: Bool = false;
            loop j in 0..length(distinct) {
                if distinct[j] == sorted[i] {
                    found = true;
                    break;
                }
            }
            if !found {
                distinct = distinct + [sorted[i]];
            }
        }

        loop i in 0..length(distinct) {
            let p: Int = distinct[i];
            let cnt: Int = 0;
            loop j in 0..n {
                if sorted[j] == p {
                    cnt = cnt + 1;
                }
            }
            println(p, ": ", cnt, " envelopes");
        }
    }
    ret;
}

