    let maxMinutes: Int = -1;
    let longestSubject: Text = "";
    let over60: Int = 0;

    loop i in 0..count {
        let row: ToonNode = toon_at(root, i);
        let subject: Text = toon_get_text_or(row, "subject", "");
        let minutes: Int = toon_get_int_or(row, "minutes", 0);
        totalMinutes = totalMinutes + minutes;
        if minutes > maxMinutes {
            maxMinutes = minutes;
            longestSubject = subject;
        }
        if minutes > 60 {
            over60 = over60 + 1;
        }
        if !toon_has_key(row, "room") {
            noRoom = noRoom + [subject];
        }
    }

    let avg: Real = 0.0;
    if count > 0 {
        avg = totalMinutes * 1.0 / count;
    }

    let noRoomText: Text = "none";
    if length(noRoom) > 0 {
        noRoomText = join(noRoom, ", ");
    }

    fx {
        println("SUBJECT COUNTS");
        println("Entries: ", count);
        println("Total minutes: ", totalMinutes);
        println("Avg minutes: ", format_float(avg, 1));
        println("No room: ", noRoomText);
        println("Longest session: ", longestSubject);
        println("Over 60 min: ", over60);
    }

    toon_close(doc);
    ret;
}

