    }

    let validCount: Int = 0;
    let invalidCount: Int = 0;
    let totalBikes: Int = 0;
    let noBikes: Int = 0;
    let noDocks: Int = 0;
    let busiestId: Text = "";
    let busiestBikes: Int = -1;
    let totalDocks: Int = 0;

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 4 {
            invalidCount = invalidCount + 1;
            continue;
        }
        let (bikes, okBikes) = try_parse_int(parts[1]);
        let (docks, okDocks) = try_parse_int(parts[2]);
        let (capacity, okCap) = try_parse_int(parts[3]);
        if !okBikes || !okDocks || !okCap {
            invalidCount = invalidCount + 1;
            continue;
        }
        if bikes < 0 || docks < 0 || bikes + docks != capacity {
            invalidCount = invalidCount + 1;
            continue;
        }
        validCount = validCount + 1;
        totalBikes = totalBikes + bikes;
        totalDocks = totalDocks + docks;
        if bikes == 0 {
            noBikes = noBikes + 1;
        }
        if docks == 0 {
            noDocks = noDocks + 1;
        }
        if bikes > busiestBikes {
            busiestBikes = bikes;
            busiestId = parts[0];
        }
    }

    let avgDocks: Real = 0.0;
    if validCount > 0 {
        avgDocks = totalDocks * 1.0 / validCount;
    }

    fx {
        println("Stations reporting: ", validCount);
        println("Invalid reports: ", invalidCount);
        println("Total bikes on network: ", totalBikes);
        println("Stations with no bikes: ", noBikes);
        println("Stations with no docks: ", noDocks);
        println("Busiest station: ", busiestId);
        println("Average docks per station: ", format_float(avgDocks, 1));
    }
    ret;
}

