        validCount = validCount + 1;
        let fine: Real = daysOut * fineRate;
        totalFines = totalFines + fine;
        if fine > largestFine {
            largestFine = fine;
        }
        if daysOut > 14 {
            overdueCount = overdueCount + 1;
            if !contains(members, memberId) {
                members = members + [memberId];
            }
        }
        if daysOut > longestDays {
            longestDays = daysOut;
            longestBook = bookId;
        }
    }

    fx {
        println("Loans checked: ", validCount);
        println("Invalid entries: ", invalidCount);
        println("Overdue loans: ", overdueCount);
        println("Total fines owed: ", format_float(round_to(totalFines, 2), 2));
        println("Largest single fine: ", format_float(round_to(largestFine, 2), 2));
        println("Longest loan: ", longestBook);
        println("Members with overdue loans: ", length(members));
    }
    ret;
}

