fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("signatures.txt"); }

    let validCount: Int = 0;
    let invalidCount: Int = 0;
    let yesCount: Int = 0;
    let noCount: Int = 0;
    let abstainCount: Int = 0;
    let ageSum: Int = 0;

    let voterIds: Text[] = [];
    let petitionIds: Text[] = [];
    let petYes: Int[] = [];
    let petNo: Int[] = [];

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 4 {
            invalidCount = invalidCount + 1;
            continue;
        }
        let pid: Text = parts[0];
        let vid: Text = parts[1];
        let ageText: Text = parts[2];
        let support: Text = parts[3];

        let (ageVal, ageOk) = try_parse_int(ageText);
        if !ageOk {
            invalidCount = invalidCount + 1;
            continue;
        }
        if ageVal < 18 {
            invalidCount = invalidCount + 1;
            continue;
        }
        if support != "yes" && support != "no" && support != "abstain" {
            invalidCount = invalidCount + 1;
            continue;
        }

        validCount = validCount + 1;
        ageSum = ageSum + ageVal;

        if !contains(voterIds, vid) {
            voterIds = voterIds + [vid];
        }

        let pIdx: Int = index_of(petitionIds, pid);
        if pIdx == -1 {
            petitionIds = petitionIds + [pid];
            petYes = petYes + [0];
            petNo = petNo + [0];
            pIdx = length(petitionIds) - 1;
        }
        if support == "yes" {
            yesCount = yesCount + 1;
            petYes[pIdx] = petYes[pIdx] + 1;
        } else if support == "no" {
            noCount = noCount + 1;
            petNo[pIdx] = petNo[pIdx] + 1;
        } else {
            abstainCount = abstainCount + 1;
        }
    }

    let majorityCount: Int = 0;
    loop i in 0..length(petitionIds) {
        if petYes[i] > petNo[i] {
            majorityCount = majorityCount + 1;
        }
    }

    let avgAge: Real;
    if validCount == 0 {
        avgAge = 0.0;
    } else {
        avgAge = round_to(ageSum * 1.0 / validCount, 1);
    }

    fx {
        println("Signatures counted: ", validCount);
        println("Invalid signatures: ", invalidCount);
        println("Distinct voters: ", length(voterIds));
        println("Yes: ", yesCount);
        println("No: ", noCount);
        println("Abstain: ", abstainCount);
        println("Average age: ", format_float(avgAge, 1));
        println("Petitions with majority yes: ", majorityCount);
    }
    ret;
}

fn main() -> Void {
    let lines: Text[] = [];
    fx {
        lines = read_lines("tickets.txt");
    }

    let valid: Int = 0;
    let invalid: Int = 0;
    let openCount: Int = 0;
    let inProgressCount: Int = 0;
    let doneCount: Int = 0;
    let unresolvedHigh: Int = 0;
    let openPrioritySum: Int = 0;

    let rooms: Int[] = [];
    let roomCounts: Int[] = [];

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 4 {
            invalid = invalid + 1;
            continue;
        }
        let ticketId: Text = parts[0];
        let roomText: Text = parts[1];
        let priorityText: Text = parts[2];
        let status: Text = parts[3];

        let (room, roomOk) = try_parse_int(roomText);
        let (priority, priorityOk) = try_parse_int(priorityText);

        let statusValid: Bool = status == "open" || status == "in_progress" || status == "done";

        if !roomOk || !priorityOk || priority < 1 || priority > 5 || !statusValid || room < 100 {
            invalid = invalid + 1;
            continue;
        }

        valid = valid + 1;

        if status == "open" {
            openCount = openCount + 1;
            openPrioritySum = openPrioritySum + priority;
        } else if status == "in_progress" {
            inProgressCount = inProgressCount + 1;
        } else {
            doneCount = doneCount + 1;
        }

        if priority >= 4 && status != "done" {
            unresolvedHigh = unresolvedHigh + 1;
        }

        let found: Bool = false;
        loop i in 0..length(rooms) {
            if rooms[i] == room {
                roomCounts[i] = roomCounts[i] + 1;
                found = true;
                break;
            }
        }
        if !found {
            rooms = rooms + [room];
            roomCounts = roomCounts + [1];
        }
    }

    let busiestRoom: Int = 0;
    let busiestCount: Int = 0;
    loop i in 0..length(rooms) {
        if busiestCount == 0 || roomCounts[i] > busiestCount || (roomCounts[i] == busiestCount && rooms[i] < busiestRoom) {
            busiestRoom = rooms[i];
            busiestCount = roomCounts[i];
        }
    }

    let avgPriority: Real = 0.0;
    if openCount > 0 {
        avgPriority = openPrioritySum * 1.0 / openCount;
    }

    fx {
        println("Tickets logged: ", valid);
        println("Invalid tickets: ", invalid);
        println("Open: ", openCount);
        println("In progress: ", inProgressCount);
        println("Done: ", doneCount);
        println("Unresolved high-priority: ", unresolvedHigh);
        println("Busiest room: ", busiestRoom);
        println("Avg priority (open): ", format_float(avgPriority, 2));
    }
    ret;
}

fn main() -> Void {
    let lines: Text[];
    fx { lines = read_lines("sightings.txt"); }

    let validCount: Int = 0;
    let invalidCount: Int = 0;
    let totalBirds: Int = 0;
    let forestCount: Int = 0;
    let wetlandCount: Int = 0;
    let urbanCount: Int = 0;
    let confSum: Real = 0.0;

    let speciesList: Text[] = [];
    let speciesCounts: Int[] = [];

    loop line in lines {
        let trimmed: Text = trim(line);
        if trimmed == "" {
            continue;
        }
        let parts: Text[] = split(trimmed, " ");
        if length(parts) != 5 {
            invalidCount = invalidCount + 1;
            continue;
        }
        let species: Text = parts[0];
        let countStr: Text = parts[1];
        let habitat: Text = parts[2];
        let distStr: Text = parts[3];
        let confStr: Text = parts[4];

        let (countVal, countOk) = try_parse_int(countStr);
        let (distVal, distOk) = try_parse_int(distStr);
        let (confVal, confOk) = try_parse_real(confStr);

        let habitatOk: Bool = habitat == "forest" || habitat == "wetland" || habitat == "urban";

        if !countOk || !distOk || !confOk || countVal < 1 || !habitatOk || confVal < 0.0 || confVal > 1.0 {
            invalidCount = invalidCount + 1;
            continue;
        }

        validCount = validCount + 1;
        totalBirds = totalBirds + countVal;
        confSum = confSum + confVal;

        if habitat == "forest" {
            forestCount = forestCount + 1;
        } else if habitat == "wetland" {
            wetlandCount = wetlandCount + 1;
        } else {
            urbanCount = urbanCount + 1;
        }

        let idx: Int = index_of(speciesList, species);
        if idx == -1 {
            speciesList = speciesList + [species];
            speciesCounts = speciesCounts + [countVal];
        } else {
            speciesCounts[idx] = speciesCounts[idx] + countVal;
        }
    }

    let distinctSpecies: Int = length(speciesList);

    let bestIdx: Int = 0;
    let bestCount: Int = 0;
    loop i in 0..length(speciesList) {
        if speciesCounts[i] > bestCount {
            bestCount = speciesCounts[i];
            bestIdx = i;
        }
    }
    let mostCommon: Text = "";
    if length(speciesList) > 0 {
        mostCommon = speciesList[bestIdx];
    }

    let avgConf: Real = 0.0;
    if validCount > 0 {
        avgConf = confSum / (validCount * 1.0);
    }

    fx {
        println("Sightings recorded: ", validCount);
        println("Invalid sightings: ", invalidCount);
        println("Total birds seen: ", totalBirds);
        println("Distinct species: ", distinctSpecies);
        println("Forest sightings: ", forestCount);
        println("Wetland sightings: ", wetlandCount);
        println("Urban sightings: ", urbanCount);
        println("Most common species: ", mostCommon);
        println("Avg confidence: ", format_float(round_to(avgConf, 2), 2));
    }
    ret;
}

