const TARGET_X: Int = 3;
const TARGET_Y: Int = 3;

fn isBlocked(x: Int, y: Int) -> Bool {
    if x == 1 && y == 1 {
        ret true;
    }
    if x == 2 && y == 0 {
        ret true;
    }
    if x == 0 && y == 2 {
        ret true;
    }
    ret false;
}

fn countPaths(x: Int, y: Int, diagUsed: Int, via22: Bool) -> (Int, Int, Int) {
    if x > TARGET_X || y > TARGET_Y {
        ret (0, 0, 0);
    }
    if isBlocked(x, y) {
        ret (0, 0, 0);
    }
    if x == TARGET_X && y == TARGET_Y {
        let t: Int = 1;
        let d: Int = 0;
        let v: Int = 0;
        if diagUsed == 2 {
            d = 1;
        }
        if via22 {
            v = 1;
        }
        ret (t, d, v);
    }
    let total: Int = 0;
    let twoDiag: Int = 0;
    let via22Count: Int = 0;
    let newVia: Bool = via22;
    if x == 2 && y == 2 {
        newVia = true;
    }
    let r: (Int, Int, Int) = countPaths(x + 1, y, diagUsed, newVia);
    total = total + r.0;
    twoDiag = twoDiag + r.1;
    via22Count = via22Count + r.2;
    let dn: (Int, Int, Int) = countPaths(x, y + 1, diagUsed, newVia);
    total = total + dn.0;
    twoDiag = twoDiag + dn.1;
    via22Count = via22Count + dn.2;
    let dg: (Int, Int, Int) = countPaths(x + 1, y + 1, diagUsed + 1, newVia);
    total = total + dg.0;
    twoDiag = twoDiag + dg.1;
    via22Count = via22Count + dg.2;
    ret (total, twoDiag, via22Count);
}

