    }
    if size % 2 == 0 && size % 3 != 0 {
        ret "Standard";
    }
    if size % 3 == 0 && size % 2 != 0 {
        ret "Economy";
    }
    ret "Sample";
}

@pure
fn pad3(n: Int) -> Text {
    if n < 10 {
        ret "00" + int_to_text(n);
    }
    if n < 100 {
        ret "0" + int_to_text(n);
    }
    ret int_to_text(n);
}

