    }
    if r == 1 {
        ret "Warm";
    }
    if r == 2 {
        ret "Hot";
    }
    if r == 3 {
        ret "Fiery";
    }
    ret "Inferno";
}

fn pad3(n: Int) -> Text {
    let s: Text = int_to_text(n);
    let len: Int = string_len(s);
    if len >= 3 {
        ret s;
    }
    let pad: Int = 3 - len;
    let zeros: Text = repeat("0", pad);
    ret zeros + s;
}

