@pure
fn digitSum(n: Int) -> Int {
    let s: Int = 0;
    let x: Int = n;
    loop {
        let d: Int = x % 10;
        s = s + d;
        x = x div 10;
        if x == 0 {
            break;
        }
    }
    ret s;
}

@pure
fn pad3(n: Int) -> Text {
    let t: Text = int_to_text(n);
    let len: Int = string_len(t);
    if len == 1 {
        ret "00" + t;
    }
    if len == 2 {
        ret "0" + t;
    }
    ret t;
}

