    loop i in 0..length(counts) {
        if counts[i] > maxCount {
            maxCount = counts[i];
        }
    }

    let bucket: Int[][] = [];
    loop c in 0..maxCount + 1 {
        let row: Int[] = [];
        bucket = bucket + [row];
    }

    loop i in 0..length(counts) {
        let c: Int = counts[i];
        let row: Int[] = bucket[c];
        row = row + [i + 1];
        bucket[c] = row;
    }

    fx {
        loop c in maxCount..-1 step -1 {
            loop slot in bucket[c] {
                println("SLOT ", slot, " CARS ", c);
            }
        }
    }
    ret;
