type Flash {
    intensity: Int = 0;
    index: Int = 0;
}

fn main() -> Void {
    let flashes: Flash[] = [
        new Flash { intensity: 540, index: 1 },
        new Flash { intensity: 610, index: 2 },
        new Flash { intensity: 585, index: 3 },
        new Flash { intensity: 610, index: 4 },
        new Flash { intensity: 575, index: 5 },
        new Flash { intensity: 540, index: 6 },
        new Flash { intensity: 610, index: 7 },
        new Flash { intensity: 575, index: 8 },
        new Flash { intensity: 540, index: 9 },
        new Flash { intensity: 610, index: 10 },
        new Flash { intensity: 585, index: 11 },
        new Flash { intensity: 575, index: 12 }
    ];

    // Insertion sort: by intensity descending, then by index ascending
    loop i in 1..length(flashes) {
        let key: Flash = flashes[i];
        let j: Int = i - 1;
        loop j >= 0 {
            let shouldSwap: Bool = false;
            if flashes[j].intensity < key.intensity {
                shouldSwap = true;
            } else if flashes[j].intensity == key.intensity && flashes[j].index > key.index {
                shouldSwap = true;
            }
            if !shouldSwap {
                break;
            }
            flashes[j + 1] = flashes[j];
            j = j - 1;
        }
        flashes[j + 1] = key;
    }

    // Assign ranks: same intensity -> same rank; next rank = position
    let ranks: Int[] = [];
    loop i in 0..length(flashes) {
        let rank: Int = i + 1;
        if i > 0 && flashes[i].intensity == flashes[i - 1].intensity {
            rank = ranks[i - 1];
        }
        ranks = ranks + [rank];
    }

    fx {
        loop i in 0..length(flashes) {
            println("OBS ", flashes[i].index, " INT ", flashes[i].intensity, " RANK ", ranks[i]);
        }
    }
    ret;
}

