    loop c in 0..4 {
        let colSum: Int = 0;
        let colMin: Int = 999999;
        loop r in 0..4 {
            colSum = colSum + S[r][c];
            if S[r][c] < colMin {
                colMin = S[r][c];
            }
        }
        colTotals = colTotals + [colSum];
        colMins = colMins + [colMin];
    }

    let scarcestIdx: Int = 0;
    loop c in 1..4 {
        if colMins[c] < colMins[scarcestIdx] {
