fn main() -> Void {
    let teams: Text[] = ["Red", "Blue", "Green", "Yellow"];
    let legs: Text[] = ["L1", "L2", "L3", "L4"];
    let T: Real[][] = [
        [12.5, 11.8, 13.2, 12.0],
        [11.9, 12.4, 12.1, 13.5],
        [13.1, 12.0, 11.7, 12.8],
        [12.3, 13.6, 12.9, 11.5]
    ];

    let totals: Real[] = [];
    loop r in 0..4 {
        let s: Real = 0.0;
        loop c in 0..4 {
            s = s + T[r][c];
        }
        totals = totals + [s];
    }

    let fastest: Real[] = [];
    let fastestTeam: Int[] = [];
    loop c in 0..4 {
        let best: Real = T[0][c];
        let bestIdx: Int = 0;
        loop r in 1..4 {
            if T[r][c] < best {
                best = T[r][c];
                bestIdx = r;
            }
        }
        fastest = fastest + [best];
        fastestTeam = fastestTeam + [bestIdx];
    }

    let winner: Int = 0;
    loop r in 1..4 {
        if totals[r] < totals[winner] {
            winner = r;
        }
    }

    let second: Int = 0;
    if winner == 0 {
        second = 1;
    } else {
        second = 0;
    }
    loop r in 0..4 {
        if r != winner && r != second {
            if totals[r] < totals[second] {
                second = r;
            }
        }
    }

    let margin: Real = totals[second] - totals[winner];

    fx {
        println("Marathon Leg Time Report");
        println("------------------------");
        loop r in 0..4 {
            println(teams[r], " total: ", format_float(totals[r], 2), " min");
        }
        loop c in 0..4 {
            println(legs[c], " fastest: ", format_float(fastest[c], 2), " by ", teams[fastestTeam[c]]);
        }
        println("Winning team: ", teams[winner]);
        println("Margin: ", format_float(margin, 2), " min");
    }
    ret;
}

