            if i < j {
                if v == 1.0 || v == 0.0 {
                    decisiveGames = decisiveGames + 1;
                }
            }
        }
        totalPoints = totalPoints + p.score;
        players = players + [p];
    }

    let topIdx: Int = 0;
    loop i in 1..4 {
        if players[i].score > players[topIdx].score {
            topIdx = i;
        }
    }

    fx {
        println("Chess Club Tournament Cross-Table");
        println("---------------------------------");
        loop i in 0..4 {
