fn main() -> Void {
    let lines: Text[] = [
        "Smith:adults=2,children=1",
        "Jones:adults=4,children=3",
        "Lee:adults=1,children=0",
        "Brown:adults=3,children=2",
        "Garcia:adults=2,children=4",
        "Wilson:adults=1,children=1"
    ];

    let grandTotal: Int = 0;
    let maxTotal: Int = -1;
    let maxFamily: Text = "";
    let moreChildren: Int = 0;

    loop line in lines {
        let colonIdx: Int = index_of(line, ":");
        let name: Text = line[0..colonIdx];
        let rest: Text = line[colonIdx + 1..];

        let commaIdx: Int = index_of(rest, ",");
        let adultsPart: Text = rest[0..commaIdx];
        let childrenPart: Text = rest[commaIdx + 1..];

        let adultsEq: Int = index_of(adultsPart, "=");
        let childrenEq: Int = index_of(childrenPart, "=");

        let adults: Int = parse_int(adultsPart[adultsEq + 1..]);
        let children: Int = parse_int(childrenPart[childrenEq + 1..]);

        let total: Int = adults + children;
        grandTotal = grandTotal + total;

        if total > maxTotal {
            maxTotal = total;
            maxFamily = name;
        }

