@pure
fn classify(interval: Int) -> Text {
    if interval <= 2 {
        ret "Frequent";
    }
    if interval <= 5 {
        ret "Regular";
    }
    ret "Rare";
}

fn main() -> Void {
    let names: Text[] = ["Rosemary", "Basil", "Thyme", "Mint", "Parsley", "Cilantro"];
    let intervals: Int[] = [7, 3, 5, 2, 4, 3];
    let frequent: Int = 0;
    let regular: Int = 0;
    let rare: Int = 0;

    loop i in 0..length(names) {
        let cat: Text = classify(intervals[i]);
        if cat == "Frequent" {
            frequent = frequent + 1;
        }
        if cat == "Regular" {
            regular = regular + 1;
        }
        if cat == "Rare" {
            rare = rare + 1;
        }
        fx {
            println("Plant: ", names[i], " | Category: ", cat);
        }
    }

    fx {
        println("Frequent: ", frequent);
        println("Regular: ", regular);
        println("Rare: ", rare);
    }
    ret;
}

@pure
fn hasSeven(n: Int) -> Bool {
    let x: Int = n;
    if x < 0 {
        x = -x;
    }
    loop {
        if x % 10 == 7 {
            ret true;
        }
        if x < 10 {
            ret false;
        }
        x = x div 10;
    }
}

fn main() -> Void {
    let moves: Int[] = [17, 25, 70, 71, 80, 97, 107, 170, 207, 777];
    let count: Int = 0;

    fx {
        println("DIGIT SEVEN CHECK");
    }

    loop i in 0..length(moves) {
        let m: Int = moves[i];
        let has: Bool = hasSeven(m);
        if has {
            count = count + 1;
        }
        fx {
            println("Move ", m, " -> Has Seven: ", if has { "Yes" } else { "No" });
        }
    }

    fx {
        println("Total Moves with Seven: ", count);
    }

    ret;
}
